{
  "findings": [
    {
      "check_id": "CKV_AWS_261",
      "title": "Ensure target group has health check enabled",
      "resource": "aws_alb_target_group.pass",
      "severity": "HIGH",
      "explanation": "The target group 'tf-example-lb-nlb-tg' does not have a health check configured, which can lead to unhealthy targets not being detected."
    }
  ],
  "patched_code": "resource "aws_alb_target_group" "pass" {
  name     = "tf-example-lb-nlb-tg"
  port     = 25
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  target_health_state {
    enable_unhealthy_connection_termination = false
  }

  health_check {
    enabled = true
    interval = 30
    port     = 25
    protocol = "TCP"
  }
}
",
  "fix_summary": "Added a health check configuration to the target group with a 30-second interval and TCP protocol."
}
